<template><ion-page><ion-header class="ion-no-border"><ion-toolbar><ion-title>Alerts</ion-title></ion-toolbar><ion-toolbar><div class="filter-row"><button v-for="item in filters" :key="item" :class="{ active: filter === item }" @click="filter = item">{{ titleCase(item) }}</button></div></ion-toolbar></ion-header><ion-content><main class="page-wrap compact-top">
  <StatePanel v-if="loading" loading title="Loading alerts" message="Checking recent farm events." /><StatePanel v-else-if="error" tone="danger" title="Unable to retrieve alerts" :message="error" :retry="load" /><StatePanel v-else-if="!visible.length" title="No alerts here" message="The selected alert category is clear." />
  <section v-else class="notification-list"><article v-for="item in visible" :key="item.id" :class="{ unread: !item.is_read }" @click="read(item)"><i :class="item.severity"></i><div><div><span>{{ item.type_display }}</span><time>{{ relativeTime(item.created_at) }}</time></div><h2>{{ item.title }}</h2><p>{{ item.description }}</p><small v-if="item.source">{{ item.source }}</small></div></article></section>
</main></ion-content></ion-page></template>
<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'; import { IonContent, IonHeader, IonPage, IonTitle, IonToolbar } from '@ionic/vue'; import StatePanel from '@/components/StatePanel.vue'; import { alertService } from '@/services/alert.service'; import type { Notification } from '@/types/api'; import { relativeTime, titleCase } from '@/utils/format';
const alerts = ref<Notification[]>([]); const filters = ['all', 'critical', 'warning', 'information']; const filter = ref('all'); const loading = ref(true); const error = ref(''); const visible = computed(() => alerts.value.filter((item) => filter.value === 'all' || (filter.value === 'critical' && ['critical', 'high'].includes(item.severity)) || (filter.value === 'warning' && ['medium', 'low'].includes(item.severity)) || (filter.value === 'information' && item.severity === 'info')));
async function load() { loading.value = true; error.value = ''; try { alerts.value = (await alertService.list()).results; } catch (reason) { error.value = reason instanceof Error ? reason.message : 'Unable to load alerts.'; } finally { loading.value = false; } }
async function read(item: Notification) { if (!item.is_read) { try { Object.assign(item, await alertService.markRead(item.id)); } catch { /* keep list usable */ } } } onMounted(load);
</script>
